#include <stdio.h>

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    if (N == 1) {
        printf("1\n");
    } else if (N == 2) {
        printf("-1\n");
    } else {
        long long S[45];

        for (int i = 0; i < N - 2; i++) {
            S[i] = i + 1;
        }

        long long X = (long long)(N - 1) * (N + 2) / 2;
        S[N - 2] = X;
        S[N - 1] = N;

        long long M = X;

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (j > 0) printf(" ");
                printf("%lld", M * S[i] + S[j]);
            }
            printf("\n");
        }
    }

    return 0;
}
